import {getConfig} from './httpClient';

export const createTicketServices = (fetchRequest: any) => ({
  async login() {
    const endPoint = '/auth/login';
    try {
      const data = await fetch(getConfig().BASE_URL_EACCOUNT + endPoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          username: 'thads@yopmail.com',
          // username: 'kyta.fpt.demo@gmail.com',
          password: 'admin@123',
        }),
      });
      return Promise.resolve(data.json());
    } catch (error) {
      return Promise.reject(error);
    }
  },
  async getListServives(body: any, params: any) {
    const endPoint = `/services/erequest/api/work-flows/search?sort=displayOrder,asc&page=${params.page}&size=${params.size}&sort=createdDate,desc`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },

  async getListServiceCode() {
    const endpoint =
      '/services/ecategory/api/data/code/RECEIPT_SERVICE?page=0&size=100';
    const data = await fetchRequest({
      url: getConfig().BASE_URL + endpoint,
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
    });
    return Promise.resolve(data?.data);
  },
});
