import {FlatList, View} from 'react-native';
import HeaderCM from '../../../../components/Header/HeaderCM';
import {styles} from './styles';
import {IconListtransferReceipt} from '../../../../../assets/images';
import ItemRelateReceipt from './component/item-relate';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useEffect, useState} from 'react';
import {useReceiptServices} from '../../../../../hooks/apiHooks/useAPI';
import {useRoute} from '@react-navigation/native';
import {ReceiptRelate} from '../../../../../model/interface/receipt.interface';
import TextCM from '../../../../components/Text';
import {useTranslation} from 'react-i18next';

const TransferReceipt = () => {
  const router = useRoute<any>();
  const {t} = useTranslation();
  const {parentId} = router?.params;
  const [listTranfer, setListTranfer] = useState<ReceiptRelate[]>([]);
  const [page, setPage] = useState(0);
  const [totalItems, setTotalItems] = useState(0);
  const [refreshing, setRefreshing] = useState(false);
  const ReceiptService = useReceiptServices();
  const getListTranfer = async (page: number) => {
    try {
      const params = {
        page: page,
        size: 20,
      };
      const body = {
        terms: {parentId: parentId},
      };
      const res = await ReceiptService.getListTranferReceiptByParentId(
        params,
        body,
      );
      if (res) {
        if (page === 0) {
          setListTranfer(res.data);
          setTotalItems(res.totalData);
        } else {
          setListTranfer([...listTranfer, ...res.data]);
        }
      }
    } catch (error) {
      console.error(error);
    } finally {
      setRefreshing(false);
    }
  };

  useEffect(() => {
    getListTranfer(0);
  }, []);

  const onRefresh = () => {
    setRefreshing(true);
    getListTranfer(0);
    setPage(0);
  };

  const onEndReached = () => {
    if (page < Math.ceil(totalItems / 20)) {
      getListTranfer(page + 1);
      setPage(page + 1);
    }
  };

  return (
    <SafeAreaView
      style={{flex: 1, backgroundColor: '#f8fafe'}}
      edges={['bottom']}>
      <HeaderCM title={t('BLDT.relate_receipt')} />
      <View style={styles.container}>
        <View style={styles.titleContainer}>
          <View style={styles.titleIconContainer}>
            <IconListtransferReceipt width={16} height={16} />
          </View>
          <TextCM style={styles.title}>{t('BLDT.list_relate_receipt')}</TextCM>
        </View>
        <FlatList
          data={listTranfer}
          refreshing={refreshing}
          onRefresh={onRefresh}
          onEndReached={onEndReached}
          onEndReachedThreshold={0.5}
          keyExtractor={item => item.data.id}
          renderItem={({item}) => <ItemRelateReceipt item={item} />}
          ItemSeparatorComponent={() => <View style={styles.separator} />}
          showsVerticalScrollIndicator={false}
          contentContainerStyle={styles.listContent}
          ListEmptyComponent={() => (
            <View
              style={{
                alignItems: 'center',
                justifyContent: 'center',
                flex: 1,
              }}>
              <TextCM>{t('CM.emptyData')}</TextCM>
            </View>
          )}
        />
      </View>
    </SafeAreaView>
  );
};
export default TransferReceipt;
