import {TouchableOpacity, View} from 'react-native';
import {styles} from './styles';
import React, {useState} from 'react';
import {useNavigation} from '@react-navigation/native';
import BottomSheetCM from '../../../../components/BottomSheet';
import HistoryTicket from '../../../my-receipt/component/history';
import {NavigationName} from '../../../../../constants';
import {DetailReceipt} from '../../../../../model/interface/receipt.interface';
import {getConfig} from '../../../../../services/httpClient';
import {useAppSelector} from '../../../../../hooks/useRedux';
import TextCM from '../../../../components/Text';
import {useTranslation} from 'react-i18next';

type Props = {
  icon: React.ReactElement;
  label: string;
  action: string;
  id: string;
  dataDetailReceipt: DetailReceipt;
};
const BottomItem = ({icon, label, action, id, dataDetailReceipt}: Props) => {
  const navigation = useNavigation<any>();
  const {t} = useTranslation();
  const [isShowModal, setIsShowModal] = useState<'history' | 'process'>();

  const {accessToken} = useAppSelector(state => state.common);
  const pressAction = () => {
    if (action === 'history') {
      setIsShowModal('history');
    } else if (action === 'info') {
      navigation.navigate(NavigationName.RecieptInfo, {
        ticketId: dataDetailReceipt.ticketId,
      });
    } else if (action === 'transfer') {
      navigation.navigate(NavigationName.TransferReceipt, {
        parentId: dataDetailReceipt.parentId,
      });
    } else if (action === 'profile') {
      navigation.navigate(NavigationName.Attachments, {
        ticketId: dataDetailReceipt.ticketId,
        receiptId: dataDetailReceipt.id,
      });
    } else if (action === 'process') {
      const url = `${getConfig().BASE_URL_TICKET}${
        dataDetailReceipt.ticketId
      }?_typeView=mine&access_token=${accessToken}`;
      navigation.navigate(NavigationName.WebViewScreen, {
        url: url,
        name: t('BLDT.view_process'),
      });
    }
  };
  return (
    <>
      <TouchableOpacity onPress={pressAction} style={styles.bottomMenuItem}>
        <View style={styles.bottomMenuIconContainer}>{icon}</View>
        <View style={{}}>
          <TextCM style={styles.bottomMenuLabel}>{t(`BLDT.${label}`)}</TextCM>
        </View>
      </TouchableOpacity>

      <BottomSheetCM
        title={t('BLDT._history')}
        onClose={() => setIsShowModal(undefined)}
        isVisible={isShowModal === 'history'}
        renderContent={
          <HistoryTicket
            onClose={() => setIsShowModal(undefined)}
            id={dataDetailReceipt.id}
          />
        }
      />
    </>
  );
};

export default BottomItem;
